function o(t){return[t.getFullYear(),String(t.getMonth()+1).padStart(2,"0"),String(t.getDate()).padStart(2,"0")].join("-")}function m(t="Europe/Rome",r=new Date){const a=new Intl.DateTimeFormat("en-CA",{timeZone:t,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(r),e=Object.fromEntries(a.map(n=>[n.type,n.value]));return new Date(Number(e.year),Number(e.month)-1,Number(e.day),12)}export{o as formatDateId,m as getDateInTimeZone};
